/**
 * Normalize a BLE UUID to full 128-bit lowercase no-dashes form so SDK lookups
 * are format-agnostic. Mirrors the normalization homey-core applies to the
 * outgoing characteristic/service/descriptor uuids in `BLECharacteristic.toJSON`
 * et al. — so app input in any common form resolves to the same cache key.
 *
 * Accepts: 16-bit ('180a'), 32-bit ('0000180a'), 128-bit with or without
 * dashes, any case. SIG-base expansion (16-bit / 32-bit -> 128-bit) uses the
 * standard BLE base UUID 00000000-0000-1000-8000-00805F9B34FB.
 *
 * Unknown lengths are returned cleaned-but-not-expanded so an invalid app
 * input still produces the same downstream "not found" error as before.
 * @param {string} uuid The UUID to normalize.
 * @returns {string} The normalized UUID.
 */
export function normalizeBleUUID(uuid: string): string;
